/* Compose reusable inside/outside selections from open lines and existing primitives. */
(()=>{'use strict';
 const core=RayRegionShape,paint=RayRegionPaintUI,scope=RayAdjustScopeUI,layer=paint.layer,toolbar=paint.toolbar,svg=layer.querySelector('svg');
 const app=document.querySelector('.film-workspace'),dock=document.createElement('section');dock.className='region-shape-dock';dock.hidden=true;dock.setAttribute('aria-label','Bảng ghép hình dưới ảnh');app.insertBefore(dock,app.querySelector('.panel'));
 const tools=document.createElement('div');tools.className='region-shape-tools';tools.setAttribute('role','group');tools.setAttribute('aria-label','Ghép nét thành hình');toolbar.append(tools);
 let tool='free',selected=-1,lastSource=null,timer=0,notice='';
 const buttons=[],actionButtons=[],strokes=()=>P.adjustRegionStrokes||[],enabled=()=>!!source&&!BEAUTY.busy&&!BODY_AI.busy,on=()=>P.adjustRegionShape==='freehand'&&P.adjustRegionPaintMode==='shape'&&scope.visible(),active=()=>on()&&P.adjustRegionDrawing;
 function button(host,label,fn,aria=label){const b=document.createElement('button');b.type='button';b.textContent=label;b.setAttribute('aria-label',aria);b.onclick=fn;host.append(b);return b;}
 function notify(message){notice=message;sync();}
 function set(next,index=selected){if(next.length>RayRegionPaint.MAX_STROKES||next.some(s=>s.points.length>core.MAX||s.points.some(p=>p.length!==2||p.some(v=>!Number.isFinite(v)||v < -16||v > 17)))||next.reduce((n,s)=>n+s.points.length,0)>8192)throw Error('Hình đã có nhiều nét hoặc điểm. Áp dụng lớp này rồi tạo vùng mới để vẽ tiếp.');P.adjustRegionStrokes=next;selected=index;}
 function act(label,fn){if(!enabled())return false;notice='';try{scope.act(label,fn);return true;}catch(e){notify(e.message||'Chưa ghép được nét. Có thể Hoàn tác để giữ vùng trước đó.');return false;}}
 function start(){act('Ghép nét thành hình',()=>{let list=strokes(),index=selected;if(P.adjustRegionShape!=='freehand'&&P.adjustRegionPlaced&&P.adjustRegion!=='all'){list=[...list,core.primitive(P.adjustRegionShape,RayAdjustScope.geometry(P),source.width,source.height,{angle:P.adjustRegionAngle,curve:P.adjustRegionCurve})];index=list.length-1;}set(list,index);P.adjustRegionShape='freehand';if(P.adjustRegion==='all')P.adjustRegion='in';P.adjustRegionPaintMode='shape';P.adjustRegionShow=P.adjustRegionPlaced=P.adjustRegionDrawing=true;tool='free';});}
 for(const row of document.querySelectorAll('.adjust-scope-bar')){const b=button(document.createElement('div'),'Ghép nét',start,'Ghép nét thành hình');b.className='adjust-region-shape';row.insertBefore(b,row.querySelector('.adjust-scope-edit'));}
 const drawing=document.createElement('div');drawing.className='region-shape-row';drawing.setAttribute('role','group');drawing.setAttribute('aria-label','Nét và cách sửa hình');tools.append(drawing);
 for(const [key,label]of [['free','Tự do'],['line','Thẳng'],['curve','Cong'],['edit','Uốn nét'],['move','Kéo hình']]){const b=button(drawing,label,()=>{tool=key;P.adjustRegionDrawing=true;sync();window.RaySession?.contextChanged();});b.dataset.shapeTool=key;buttons.push(b);}
 const actions=document.createElement('div');actions.className='region-shape-row';tools.append(actions);
 const primitive=document.createElement('select');primitive.setAttribute('aria-label','Thêm hình có sẵn vào vùng vẽ');for(const [value,label]of [['','＋ Hình có sẵn'],['ellipse','Oval'],['rect','Chữ nhật'],['beam','Tam giác'],['line','Nét thẳng'],['curve','Nét cong']]){const o=document.createElement('option');o.value=value;o.textContent=label;primitive.append(o);}actions.append(primitive);
 function addPrimitive(shape){act('Thêm hình vào vùng vẽ',()=>{const L=Math.min(source.width,source.height),f={cx:.5,cy:.5,rx:L*.17/source.width,ry:L*.17/source.height};set([...strokes(),core.primitive(shape,f,source.width,source.height,{curve:.7})],strokes().length);P.adjustRegionDrawing=true;tool=shape==='line'||shape==='curve'?'free':'move';});primitive.value='';}
 primitive.onchange=()=>{if(primitive.value)addPrimitive(primitive.value);};
 const close=button(actions,'Khép hình',()=>act('Khép đường bao',()=>{const s=strokes()[selected];if(!s||s.points.length<3)throw Error('Vẽ ít nhất ba điểm tạo thành đường bao rồi khép hình.');set(strokes().map((q,i)=>i===selected?core.close(q):q));tool='edit';}));actionButtons.push(close);
 button(actions,'＋ Hình mới',()=>{selected=-1;tool='free';P.adjustRegionDrawing=true;notice='Bắt đầu đường bao mới trên ảnh. Các hình trước vẫn được giữ.';sync();});
 const borrow=document.createElement('select');borrow.setAttribute('aria-label','Tận dụng nét đã vẽ');for(const [value,label]of [['','Lấy nét đã vẽ…'],['body','Nét ở Chỉnh dáng'],['paint','Nét vùng đã tô']]){const o=document.createElement('option');o.value=value;o.textContent=label;borrow.append(o);}actions.append(borrow);
 function importBody(){return act('Dùng nét chỉnh dáng làm vùng',()=>{const paths=window.RayBodyLines?.paths?.()||[];if(!paths.length)throw Error('Chưa có nét ở Chỉnh dáng. Có thể vẽ hình ngay tại đây.');const imported=core.importPaths(paths,source.width,source.height),all=[...strokes(),...imported];set(all,all.length-1);const joined=core.join(all,selected,18/(bodyGeo()?.k||1)*source.width/(bodyGeo()?.W||source.width),source.width,source.height);set(joined.strokes,joined.index);P.adjustRegionDrawing=true;tool='free';});}
 borrow.onchange=()=>{if(borrow.value==='body')importBody();else if(borrow.value==='paint')act('Nối các nét vùng đã tô',()=>{const list=strokes().map(s=>s.mode==='paint'?{...s,mode:'lasso',open:true}:s);let result=list,index=list.findLastIndex(s=>s.open);if(index<0)throw Error('Chưa có nét tô để ghép. Chọn Tự do, Thẳng hoặc Cong để vẽ.');for(let i=result.length-1;i>=0;i--)if(result[i]?.open){const joined=core.join(result,i,Math.min(source.width,source.height)*.025,source.width,source.height);result=joined.strokes;index=joined.index;}set(result,index);tool='free';P.adjustRegionDrawing=true;});borrow.value='';};
 const sides=document.createElement('div');sides.className='region-shape-row';tools.append(sides);const sideButtons=[];for(const [value,label]of [['in','Trong hình'],['out','Ngoài hình']]){const b=button(sides,label,()=>act(label,()=>{P.adjustRegion=value;P.adjustRegionShow=true;}));b.dataset.shapeSide=value;sideButtons.push(b);}
 const remove=button(sides,'Xóa hình này',()=>act('Xóa một hình trong vùng',()=>{set(strokes().filter((_,i)=>i!==selected),-1);}));actionButtons.push(remove);
 const help=document.createElement('span');help.className='region-shape-help';help.setAttribute('role','status');help.setAttribute('aria-live','polite');tools.append(help);
 const guides=document.createElementNS(svg.namespaceURI,'g');guides.classList.add('region-shape-guides');svg.append(guides);
 function el(tag,attrs){const e=document.createElementNS(svg.namespaceURI,tag);for(const [k,v]of Object.entries(attrs))e.setAttribute(k,String(v));guides.append(e);return e;}
 function path(points,closed){return'M'+points.map(p=>p[0]*1000+' '+p[1]*1000).join('L')+(closed?'Z':'');}
 function dot(p,g,r=4,kind=''){el('ellipse',{cx:p[0]*1000,cy:p[1]*1000,rx:r/(g.W*g.k)*1000,ry:r/(g.H*g.k)*1000,class:'region-shape-dot '+kind});}
 function handles(s,g){const b=core.bounds(s.points);return{size:[b.right,b.bottom],rotate:[(b.left+b.right)/2,Math.max(.015,b.top-22/(g.H*g.k))],center:[(b.left+b.right)/2,(b.top+b.bottom)/2],...b};}
 function sync(){
  if(source!==lastSource){lastSource=source;selected=-1;tool='free';notice='';}const visible=on(),drawing=active();tools.hidden=!drawing;toolbar.classList.toggle('is-shape-builder',drawing);dock.hidden=!drawing;if(app.classList.contains('region-shape-building')!==drawing)app.classList.toggle('region-shape-building',drawing);if(drawing&&toolbar.parentElement!==dock)dock.append(toolbar);else if(!drawing&&toolbar.parentElement!==document.getElementById('canvasWrap'))document.getElementById('canvasWrap').append(toolbar);guides.replaceChildren();
  const list=strokes();if(selected>=list.length||selected>=0&&list[selected].mode!=='lasso')selected=list.findLastIndex(s=>s.mode==='lasso');
  for(const b of document.querySelectorAll('.adjust-region-shape')){b.disabled=!enabled();b.setAttribute('aria-pressed',String(drawing));}
  for(const b of buttons){b.disabled=!enabled();b.setAttribute('aria-pressed',String(drawing&&b.dataset.shapeTool===tool));}for(const b of sideButtons)b.setAttribute('aria-pressed',String(P.adjustRegion===b.dataset.shapeSide));for(const b of actionButtons)b.disabled=!enabled()||selected<0;close.disabled=close.disabled||!list[selected]?.open;primitive.disabled=borrow.disabled=!enabled();
  const open=list.filter(s=>s.mode==='lasso'&&s.open).length;help.textContent=notice||(open?'Chạm đầu nét để nối tiếp. Khép hình để lấy phần trong; Thẳng / Cong có thể nối cùng nét tự do.':'Vẽ hoặc ghép hình bất kỳ. Chọn Trong / Ngoài để áp preset và các thanh màu.');
  if(!visible||!P.adjustRegionDrawing)return;const g=bodyGeo();if(!g)return;for(let i=0;i<list.length;i++){const s=list[i];if(s.mode!=='lasso')continue;el('path',{d:path(s.points,!s.open),class:i===selected?'region-shape-selected':'region-shape-path'});if(s.open&&s.points.length){dot(s.points[0],g,5,'start');dot(s.points.at(-1),g,4);}}
  const s=list[selected];if(!s)return;if(tool==='edit'){const step=Math.max(1,Math.ceil(s.points.length/14));for(let i=0;i<s.points.length;i+=step)dot(s.points[i],g,3);}else if(tool==='move'){const h=handles(s,g);el('path',{d:path([[h.left,h.top],[h.right,h.top],[h.right,h.bottom],[h.left,h.bottom]],true),class:'region-shape-box'});dot(h.size,g,7,'handle');dot(h.rotate,g,7,'handle');}
 }
 function point(g,e){return[clamp((e.clientX-g.ox)/(g.W*g.k),0,1),clamp((e.clientY-g.oy)/(g.H*g.k),0,1)];}
 function apply(){clearTimeout(timer);timer=0;RayLayers.updateScope();RayAdjustScope.invalidate();scope.sync();queue();}
 function publish(next,index,immediate=false){set(next,index);paint.sync();if(immediate)apply();else if(!timer)timer=setTimeout(apply,90);}
 function finish(){if(!strokes().some(s=>s.mode==='lasso'&&s.open&&s.points.length>=3))return true;return act('Khép các hình đã vẽ',()=>set(strokes().map(s=>s.mode==='lasso'&&s.open&&s.points.length>=3?core.close(s):s)));}
 RayControls.bindDrag(layer,{
  start(e){if(!enabled()||!active())return;const g=bodyGeo();if(!g)return;const p=point(g,e),list=strokes();notice='';window.RaySession?.record();
   if(tool==='edit'||tool==='move'){let hit=core.hit(list,p,g.W*g.k,g.H*g.k,23),kind=tool;const s=list[selected];if(tool==='move'&&s){const h=handles(s,g);if(core.distance(p,h.size,g.W*g.k,g.H*g.k)<23){hit={index:selected};kind='resize';}else if(core.distance(p,h.rotate,g.W*g.k,g.H*g.k)<23){hit={index:selected};kind='rotate';}}
    if(!hit){notify('Chạm sát đường bao để chọn hình. Chọn Tự do, Thẳng hoặc Cong để thêm nét.');return;}selected=hit.index;sync();return{kind,source,g,before:list,index:selected,stroke:list[selected],point:hit.point,start:p,handles:handles(list[selected],g)};
   }
   let index=selected,prefix=[];const s=list[index],tol=18;if(s?.mode==='lasso'&&s.open){if(core.distance(p,s.points.at(-1),g.W*g.k,g.H*g.k)<tol)prefix=s.points;else if(core.distance(p,s.points[0],g.W*g.k,g.H*g.k)<tol)prefix=s.points.slice().reverse();}
   const base=prefix.length?list:list.concat({mode:'lasso',open:true,size:.006,points:[]});if(!prefix.length)index=base.length-1;const anchor=prefix.at(-1)||p,gesture={kind:tool,source,g,before:base,index,prefix,anchor,points:[anchor]};RayRegionPaint.interactive=true;try{publish(base.map((q,i)=>i===index?{...q,points:core.append(prefix,[anchor])}:q),index,true);}catch(err){notify(err.message);return;}return gesture;},
  move(s,e){if(source!==s.source)return;const p=point(s.g,e);try{
    if(['edit','move','resize','rotate'].includes(s.kind)){let points;const dx=(p[0]-s.start[0])*source.width,dy=(p[1]-s.start[1])*source.height;if(s.kind==='edit')points=core.bend(s.stroke.points,s.point,dx,dy,source.width,source.height,P.adjustRegionBrushSize||.12);else if(s.kind==='move')points=core.transform(s.stroke.points,source.width,source.height,{dx,dy});else if(s.kind==='resize'){const h=s.handles;points=core.transform(s.stroke.points,source.width,source.height,{sx:clamp((p[0]-h.center[0])/(s.start[0]-h.center[0]||.01),.08,6),sy:clamp((p[1]-h.center[1])/(s.start[1]-h.center[1]||.01),.08,6)});}else{const h=s.handles,c=h.center,angle=(Math.atan2((p[1]-c[1])*source.height,(p[0]-c[0])*source.width)-Math.atan2((s.start[1]-c[1])*source.height,(s.start[0]-c[0])*source.width))*180/Math.PI;points=core.transform(s.stroke.points,source.width,source.height,{angle});}publish(s.before.map((q,i)=>i===s.index?{...s.stroke,points}:q),s.index);return;}
    s.points=s.kind==='free'?RayRegionPaint.append(s.points,p,.001):core.segment(s.anchor,p,s.kind,source.width,source.height);publish(s.before.map((q,i)=>i===s.index?{...q,points:core.append(s.prefix,s.points)}:q),s.index);
   }catch(err){notify(err.message);}},
  end(s){RayRegionPaint.interactive=false;if(source!==s.source)return;try{if(!['edit','move','resize','rotate'].includes(s.kind)){const tol=18/(s.g.W*s.g.k)*source.width,result=core.join(strokes(),s.index,tol,source.width,source.height);set(result.strokes,result.index);}apply();sync();window.RaySession?.record('Ghép và sửa hình vùng áp dụng');}catch(e){notify(e.message);}}
 });
 const bodyPane=document.getElementById('rayBodyLinesPane');if(bodyPane){const b=button(bodyPane,'Dùng nét làm vùng Trong / Ngoài',()=>{window.BuongToiApp.showTools('film');start();importBody();});b.className='region-shape-from-body';}
 window.RayRegionShapeUI={start,sync,finish,addPrimitive,importBody,get active(){return active();}};sync();
})();
